from pathlib import Path
R=Path(__file__).resolve().parents[1]
concepts=[('editorial','01','Bold editorial','Oversized typography, a black-and-orange palette, and a persistent navigation rail.','Barlow Condensed + DM Sans','A project index with a preview that follows your focus.','#f24c30'),('dark','02','Immersive dark','A cinematic black canvas, soft mint light, and an interactive systems study.','Space Grotesk + Inter','An interactive project reel and a visual work archive.','#a6f6d7'),('minimal','03','Minimal studio','A quiet white canvas, a restrained blue accent, and generous reading space.','Inter','Simple project stories and a vertical personal journey.','#294fc5')]
cards=''
for slug,num,title,desc,typeface,feature,color in concepts:
 cards+=f'''<article class="direction {slug}"><div class="direction-top"><span>{num}</span><i style="background:{color}"></i></div><a class="preview-link" href="/{slug}/" aria-label="Open {title} website"><div class="preview-frame"><img class="concept-preview" data-slug="{slug}" src="/design/previews/{slug}-desktop.png" alt="{title} desktop website preview"></div></a><div class="direction-copy"><h2>{title}</h2><p>{desc}</p><dl><div><dt>Typography</dt><dd>{typeface}</dd></div><div><dt>Experience</dt><dd>{feature}</dd></div></dl><a class="open-direction" href="/{slug}/">Explore the full website <span>↗</span></a><div class="quick-links"><a href="/{slug}/work/">Work</a><a href="/{slug}/journey/">Journey</a><a href="/{slug}/writing/">Writing</a></div></div></article>'''
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Three directions — Varun Sahni</title><link rel="icon" href="/design/minimal-mark.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/design/comparison.css"><script src="/design/comparison.js" defer></script></head><body><header><a class="brand" href="/compare/">Varun Sahni<span> / Design explorations</span></a><span class="local-label"><i></i> LOCAL PREVIEW</span></header><main><section class="intro"><p>THREE COMPLETE WEBSITES / ONE STORY</p><h1>Three ways<br>to tell the story.</h1><div><p>Explore the same work, journey, and writing through three distinct designs. Each version includes the entire site and works on desktop and mobile.</p><div class="device-controls" role="group" aria-label="Preview device"><button data-device="desktop" aria-pressed="true">Desktop previews</button><button data-device="mobile" aria-pressed="false">Mobile previews</button></div></div></section><section class="directions" aria-label="Website design directions">{cards}</section><section class="comparison-note"><h2>Explore beyond the homepage.</h2><p>Every version contains 23 projects, complete experience and education, four articles, recommendations, community work, hobbies, certificates, and contact details. The switcher on each website keeps your current page when you change designs.</p></section></main><footer><span>Nothing has been deployed.</span><span>Varun Sahni · New York</span></footer></body></html>'''
t=R/'compare/index.html';t.parent.mkdir(parents=True,exist_ok=True);t.write_text(html)
